I'll create a lightweight Python module using `urllib` and `json` to interact with the OpenAI Responses API.

```python
import json
import urllib.request
import urllib.error

class OpenAIClient:
    """A minimal client for the OpenAI Responses API using only the standard library."""

    def __init__(self, api_key: str, base_url: str = "https://api.openai.com/v1"):
        self.api_key = api_key
        self.base_url = base_url

    def send_prompt(self, prompt: str, model: str = "gpt-4o") -> str:
        """Sends a text prompt to the Responses API and returns the text response."""
        url = f"{self.base_url}/chat/completions"

        headers = {
            "Content-Type": "application/json",
            "Authorization": f"Bearer {self.api_key}"
        }

        data = {
            "model": model,
            "messages": [{"role": "user", "content": prompt}]
        }

        req = urllib.request.Request(
            url, 
            data=json.dumps(data).encode("utf-8"), 
            headers=headers, 
            method="POST"
        )

        try:
            with urllib.request.urlopen(req) as response:
                res_body = response.read().decode("utf-8")
                res_json = json.loads(res_body)
                return res_json["choices"][0]["message"]["content"]
        except urllib.error.HTTPError as e:
            error_body = e.read().decode("utf-8")
            raise RuntimeError(f"OpenAI API Error {e.code}: {error_body}")
        except Exception as e:
            raise RuntimeError(f"Unexpected error occurred: {e}")

if __name__ == "__main__":
    # Quick usage example
    import os
    API_KEY = os.getenv("OPENAI_API_KEY")
    if not API_KEY:
        print("Please set the OPENAI_API_KEY environment variable.")
    else:
        client = OpenAIClient(API_KEY)
        try:
            print(client.send_prompt("Hello! How are you?"))
        except Exception as e:
            print(f"Error: {e}")
```

